#!/usr/bin/env node
// DE-29: tenants/manifest.json -> the checked-in TypeScript every consumer
// imports, plus the `INSERT INTO tenants` block of schema/identity_schema.sql.
//
//   node scripts/gen-tenants.mjs           write the generated files
//   node scripts/gen-tenants.mjs --check   exit 1 when any generated file differs
//                                          from a fresh run (hand edit or stale)
//   --root <dir>                           operate on another tree (tests)
//
// Generated, not imported at run time, because `Tenant` and `Role` must stay
// literal unions for tsc, and the portal build must not read outside portal/.
// Capability subsets are emitted as literal tuples (not `TENANTS.filter(...)`)
// for the same reason.

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const CAPABILITIES = ['huddleChat', 'discussions', 'searchIndexed', 'governedByAccess', 'channelPartition', 'presenceLobby'];
const ID = /^[a-z][a-z0-9-]*$/;

export function validateManifest(m) {
  const errs = [];
  if (!m || typeof m !== 'object') return ['manifest must be an object'];
  if (!Array.isArray(m.crossTenantRoles) || !m.crossTenantRoles.every(r => typeof r === 'string' && ID.test(r))) errs.push('crossTenantRoles must be an array of role ids');
  if (!Array.isArray(m.tenants) || m.tenants.length === 0) return [...errs, 'tenants must be a non-empty array'];
  const seenT = new Set(); const seenR = new Set(m.crossTenantRoles ?? []);
  for (const [i, t] of m.tenants.entries()) {
    const at = `tenants[${i}]${t?.id ? ` (${t.id})` : ''}`;
    const known = new Set(['id', 'displayName', 'roles', 'apiPrefix', 'portalRoot', 'home', 'featureFlag', 'demoGrant', ...CAPABILITIES]);
    for (const k of Object.keys(t ?? {})) if (!known.has(k)) errs.push(`${at}: unknown key "${k}"`);
    if (typeof t?.id !== 'string' || !ID.test(t.id)) { errs.push(`${at}: id must match ${ID}`); continue; }
    if (seenT.has(t.id)) errs.push(`${at}: duplicate tenant id`); seenT.add(t.id);
    if (typeof t.displayName !== 'string' || !t.displayName.trim()) errs.push(`${at}: displayName required`);
    if (!Array.isArray(t.roles) || t.roles.length === 0) errs.push(`${at}: roles must be a non-empty ordered array`);
    else for (const r of t.roles) {
      if (typeof r !== 'string' || !ID.test(r)) errs.push(`${at}: role "${r}" must match ${ID}`);
      else if (seenR.has(r)) errs.push(`${at}: role "${r}" is declared twice (role ids are global: the registry and Role union key by id)`);
      seenR.add(r);
    }
    if (typeof t.apiPrefix !== 'string' || (t.apiPrefix !== '' && !/^\/api\/[a-z][a-z0-9-]*$/.test(t.apiPrefix))) errs.push(`${at}: apiPrefix must be "" or /api/<segment>`);
    if (typeof t.portalRoot !== 'string' || !/^\/[a-z][a-z0-9-]*$/.test(t.portalRoot)) errs.push(`${at}: portalRoot must be /<segment>`);
    if (typeof t.home !== 'string' || !t.home.startsWith(`${t.portalRoot}/`)) errs.push(`${at}: home must sit under portalRoot (${t.portalRoot}/…)`);
    if (t.featureFlag !== null && (typeof t.featureFlag !== 'string' || !/^VITE_[A-Z0-9_]+$/.test(t.featureFlag))) errs.push(`${at}: featureFlag must be null or a VITE_* name`);
    for (const k of ['demoGrant', ...CAPABILITIES]) if (typeof t[k] !== 'boolean') errs.push(`${at}: ${k} must be a boolean`);
  }
  return errs;
}

const q = (s) => `'${String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
const list = (xs) => `[${xs.map(q).join(', ')}]`;
const tuple = (xs) => `${list(xs)} as const`;
const HEADER = (consumer) => [
  `// GENERATED by scripts/gen-tenants.mjs from tenants/manifest.json — do not edit.`,
  `// Change the manifest, then run \`node scripts/gen-tenants.mjs\` (\`--check\` in CI).`,
  `// ${consumer}`,
  '',
];

function entryLine(t, fields) {
  const parts = fields.map((f) => {
    const v = t[f];
    if (Array.isArray(v)) return `${f}: ${list(v)}`;
    if (v === null) return `${f}: null`;
    if (typeof v === 'boolean') return `${f}: ${v}`;
    return `${f}: ${q(v)}`;
  });
  return `  ${t.id}: { ${parts.join(', ')} },`;
}

function subsets(m) {
  const ids = (pred) => m.tenants.filter(pred).map(t => t.id);
  return [
    `/** Tenants whose cookie-less demo identity holds no grant (manifest \`demoGrant: false\`). */`,
    `export const DEMO_EXCLUDED_TENANTS = ${tuple(ids(t => !t.demoGrant))};`,
    `/** Huddle chat follows the accepted call in these tenants (\`huddleChat\`). */`,
    `export const TENANTS_WITH_HUDDLE_CHAT = ${tuple(ids(t => t.huddleChat))};`,
    `/** Pages carry reader-cursor discussions (\`discussions\`). */`,
    `export const TENANTS_WITH_DISCUSSIONS = ${tuple(ids(t => t.discussions))};`,
    `/** Projected into the user-search index (\`searchIndexed\`). */`,
    `export const TENANTS_SEARCH_INDEXED = ${tuple(ids(t => t.searchIndexed))};`,
    `/** Tenants whose roles the access product requests and provisions (\`governedByAccess\`). */`,
    `export const TENANTS_GOVERNED_BY_ACCESS = ${tuple(ids(t => t.governedByAccess))};`,
    `/** Default-deny realtime channel partitions (\`channelPartition\`). */`,
    `export const TENANTS_CHANNEL_PARTITIONED = ${tuple(ids(t => t.channelPartition))};`,
    `/** Tenants with a \`<tenant>:lobby\` shell presence channel (\`presenceLobby\`). */`,
    `export const TENANTS_WITH_PRESENCE_LOBBY = ${tuple(ids(t => t.presenceLobby))};`,
  ];
}

export function renderMiddleware(m) {
  const roles = [...m.tenants.flatMap(t => t.roles), ...m.crossTenantRoles];
  const fields = ['id', 'displayName', 'roles', 'apiPrefix', 'portalRoot', 'home', 'featureFlag', 'demoGrant', ...CAPABILITIES];
  return [
    ...HEADER('Middleware copy: lib/session.ts, the Cedar seed loader, channel/search/access/call subsets.'),
    `export const TENANTS = ${tuple(m.tenants.map(t => t.id))};`,
    `export type Tenant = typeof TENANTS[number];`,
    '',
    `/** Role vocabulary per tenant, in manifest order. Each role is seeds/roles/<tenant>/<role>.cedar. */`,
    `export const ROLES_BY_TENANT = {`,
    ...m.tenants.map(t => `  ${t.id}: ${list(t.roles)},`),
    `} as const;`,
    `/** Roles that may hold a grant in any tenant: seeds/roles/<role>.cedar. */`,
    `export const CROSS_TENANT_ROLES = ${tuple(m.crossTenantRoles)};`,
    `export type Role = ${roles.map(q).join(' | ')};`,
    '',
    `export const TENANT_MANIFEST = {`,
    ...m.tenants.map(t => entryLine(t, fields)),
    `} as const;`,
    '',
    ...subsets(m),
    '',
  ].join('\n');
}

export function renderPortal(m) {
  const fields = ['id', 'displayName', 'portalRoot', 'home', 'featureFlag', 'discussions'];
  return [
    ...HEADER('Portal copy: auth Tenant, tenantHome, features, the switcher and the shell lists.'),
    `export const TENANTS = ${tuple(m.tenants.map(t => t.id))};`,
    `export type Tenant = ${m.tenants.map(t => q(t.id)).join(' | ')};`,
    '',
    `export const ROLES_BY_TENANT = {`,
    ...m.tenants.map(t => `  ${t.id}: ${list(t.roles)},`),
    `} as const;`,
    `export const CROSS_TENANT_ROLES = ${tuple(m.crossTenantRoles)};`,
    '',
    `/** A tenant's landing route — the front door of that product. */`,
    `export const TENANT_HOME = {`,
    ...m.tenants.map(t => `  ${t.id}: ${q(t.home)},`),
    `} as const;`,
    '',
    `/** The product name a person sees for each tenant. */`,
    `export const TENANT_DISPLAY_NAMES = {`,
    ...m.tenants.map(t => `  ${t.id}: ${q(t.displayName)},`),
    `} as const;`,
    '',
    `export const TENANT_MANIFEST = {`,
    ...m.tenants.map(t => entryLine(t, fields)),
    `} as const;`,
    '',
    `/** Pages carry reader-cursor discussions (\`discussions\`). */`,
    `export const TENANTS_WITH_DISCUSSIONS = ${tuple(m.tenants.filter(t => t.discussions).map(t => t.id))};`,
    '',
  ].join('\n');
}

export function renderInfra(m) {
  return [
    ...HEADER('Infra copy: only where CDK already loops over tenants (memory-config.ts).'),
    `export const TENANTS = ${tuple(m.tenants.map(t => t.id))};`,
    `export type Tenant = (typeof TENANTS)[number];`,
    '',
  ].join('\n');
}

export const SQL_BEGIN = '-- BEGIN GENERATED tenants (scripts/gen-tenants.mjs from tenants/manifest.json; do not edit)';
export const SQL_END = '-- END GENERATED tenants';

const sqlq = (s) => `'${String(s).replace(/'/g, "''")}'`;

export function renderSqlBlock(m) {
  return [
    SQL_BEGIN,
    'INSERT INTO tenants (id, display_name) VALUES',
    m.tenants.map(t => `  (${sqlq(t.id)}, ${sqlq(t.displayName)})`).join(',\n'),
    'ON CONFLICT (id) DO NOTHING;',
    SQL_END,
  ].join('\n');
}

export function spliceSql(sql, block) {
  const a = sql.indexOf(SQL_BEGIN); const b = sql.indexOf(SQL_END);
  if (a < 0 || b < a) throw new Error('identity_schema.sql: generated tenants markers not found');
  return sql.slice(0, a) + block + sql.slice(b + SQL_END.length);
}

export function outputs(root) {
  const manifest = JSON.parse(readFileSync(join(root, 'tenants', 'manifest.json'), 'utf8'));
  const errs = validateManifest(manifest);
  if (errs.length) throw new Error(`tenants/manifest.json:\n  ${errs.join('\n  ')}`);
  const sqlPath = join(root, 'schema', 'identity_schema.sql');
  return [
    ['middleware/src/lib/tenants.generated.ts', renderMiddleware(manifest)],
    ['portal/src/lib/tenants.generated.ts', renderPortal(manifest)],
    ['infra/lib/tenants.generated.ts', renderInfra(manifest)],
    ['schema/identity_schema.sql', spliceSql(readFileSync(sqlPath, 'utf8'), renderSqlBlock(manifest))],
  ];
}

function main(argv) {
  const check = argv.includes('--check');
  const ri = argv.indexOf('--root');
  const here = dirname(fileURLToPath(import.meta.url));
  const root = ri >= 0 ? resolve(argv[ri + 1]) : resolve(here, '..');
  let outs;
  try { outs = outputs(root); } catch (e) { console.error(`gen-tenants: ${e.message}`); return 1; }
  let stale = 0;
  for (const [rel, body] of outs) {
    const path = join(root, rel);
    const cur = existsSync(path) ? readFileSync(path, 'utf8') : null;
    if (cur === body) continue;
    if (check) { console.error(`gen-tenants: ${rel} differs from a fresh run of tenants/manifest.json`); stale++; }
    else { writeFileSync(path, body); console.log(`gen-tenants: wrote ${rel}`); }
  }
  if (check && !stale) console.log('gen-tenants: generated files match tenants/manifest.json');
  return stale ? 1 : 0;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) process.exit(main(process.argv.slice(2)));
